//! Polygon offsetting engine (Clipper2-style "square / round / miter" joins).
//!
//! For each vertex of a closed polygon the adjacent edge normals are used to
//! place offset vertices according to the join type, exactly as Clipper2's
//! ClipperOffset does before its union cleanup pass. For the inputs handled
//! here (simple polygons that do not self-intersect after offsetting) the raw
//! offset contour is already the final result, so each surviving contour is
//! returned as one output polygon.

use super::{EndType, JoinType, Path64, Paths64, Point64};

/// Maximum miter length relative to delta before a miter join is squared off
/// (Clipper2's default MiterLimit is 2.0).
const DEFAULT_MITER_LIMIT: f64 = 2.0;

/// Tolerance used to decide how many line segments approximate a round join.
const ARC_TOLERANCE: f64 = 0.25;

#[derive(Clone, Copy)]
struct Vec2 {
    x: f64,
    y: f64,
}

impl Vec2 {
    fn dot(self, o: Vec2) -> f64 {
        self.x * o.x + self.y * o.y
    }
    fn cross(self, o: Vec2) -> f64 {
        self.x * o.y - self.y * o.x
    }
}

/// Signed area of a closed path (positive = counter-clockwise).
fn area(path: &Path64) -> f64 {
    let n = path.len();
    let mut a = 0.0f64;
    for i in 0..n {
        let j = if i == 0 { n - 1 } else { i - 1 };
        a += (path[j].x as f64 + path[i].x as f64) * (path[j].y as f64 - path[i].y as f64);
    }
    a * 0.5
}

/// Unit normal of edge a->b pointing to the right of the edge direction,
/// i.e. outward for counter-clockwise (positive-area) polygons.
fn unit_normal(a: Point64, b: Point64) -> Vec2 {
    let dx = (b.x - a.x) as f64;
    let dy = (b.y - a.y) as f64;
    if dx == 0.0 && dy == 0.0 {
        return Vec2 { x: 0.0, y: 0.0 };
    }
    let f = 1.0 / dx.hypot(dy);
    Vec2 {
        x: dy * f,
        y: -dx * f,
    }
}

fn strip_duplicates(path: &mut Path64) {
    path.dedup();
    while path.len() > 1 && path.first() == path.last() {
        path.pop();
    }
}

fn push_point(out: &mut Path64, pt: Point64, nx: f64, ny: f64, delta: f64) {
    out.push(Point64::new(
        (pt.x as f64 + nx * delta).round() as i64,
        (pt.y as f64 + ny * delta).round() as i64,
    ));
}

/// Convex vertex: emit the join between the two offset edges.
fn do_join(out: &mut Path64, pt: Point64, n_prev: Vec2, n_curr: Vec2, sin_a: f64, cos_a: f64, delta: f64, jt: JoinType) {
    match jt {
        JoinType::Miter => {
            // miter length / delta = 1 / cos(a/2); square off when it
            // exceeds the miter limit.
            let miter_ratio = (2.0 / (1.0 + cos_a)).sqrt();
            if miter_ratio <= DEFAULT_MITER_LIMIT {
                let k = delta / (1.0 + cos_a);
                out.push(Point64::new(
                    (pt.x as f64 + (n_prev.x + n_curr.x) * k).round() as i64,
                    (pt.y as f64 + (n_prev.y + n_curr.y) * k).round() as i64,
                ));
            } else {
                do_join(out, pt, n_prev, n_curr, sin_a, cos_a, delta, JoinType::Square);
            }
        }
        JoinType::Square => {
            // Extend each offset edge by tan(a/2) * delta along the edge so
            // the corner is squared off.
            let tan = sin_a / (1.0 + cos_a);
            out.push(Point64::new(
                (pt.x as f64 + delta * (n_prev.x - n_prev.y * tan)).round() as i64,
                (pt.y as f64 + delta * (n_prev.y + n_prev.x * tan)).round() as i64,
            ));
            out.push(Point64::new(
                (pt.x as f64 + delta * (n_curr.x + n_curr.y * tan)).round() as i64,
                (pt.y as f64 + delta * (n_curr.y - n_curr.x * tan)).round() as i64,
            ));
        }
        JoinType::Round => {
            let angle = sin_a.atan2(cos_a).abs();
            let abs_delta = delta.abs();
            // steps needed to keep the arc within ARC_TOLERANCE of a circle
            let step_angle = if abs_delta > ARC_TOLERANCE {
                (1.0 - ARC_TOLERANCE / abs_delta).acos() * 2.0
            } else {
                std::f64::consts::PI / 2.0
            };
            let steps = (angle / step_angle).ceil().max(1.0);
            let step = angle / steps;
            // rotate n_prev towards n_curr around pt
            let (sin0, cos0) = (sin_a, cos_a);
            push_point(out, pt, n_prev.x, n_prev.y, delta);
            for i in 1..steps as usize {
                let a = step * i as f64;
                // rotate n_prev by `a` in the direction of the turn
                let (s, c) = (a.sin() * sin0.signum(), a.cos());
                let nx = n_prev.x * c - n_prev.y * s;
                let ny = n_prev.x * s + n_prev.y * c;
                push_point(out, pt, nx, ny, delta);
            }
            let _ = (sin0, cos0);
            push_point(out, pt, n_curr.x, n_curr.y, delta);
        }
    }
}

/// Offset one closed polygon; returns the raw offset contour (may be empty
/// when a negative delta erodes the polygon away entirely).
fn offset_polygon(path: &Path64, delta: f64, jt: JoinType) -> Path64 {
    let n = path.len();
    let normals: Vec<Vec2> = (0..n)
        .map(|i| unit_normal(path[i], path[(i + 1) % n]))
        .collect();

    // For clockwise paths the right-hand normals point inward; flip delta
    // so positive delta always expands the polygon.
    let d = if area(path) < 0.0 { -delta } else { delta };

    let mut out: Path64 = Vec::new();
    for j in 0..n {
        let k = if j == 0 { n - 1 } else { j - 1 };
        let n_prev = normals[k];
        let n_curr = normals[j];
        let sin_a = n_prev.cross(n_curr);
        let cos_a = n_prev.dot(n_curr);
        let pt = path[j];

        if sin_a > 1e-12 {
            // convex vertex
            do_join(&mut out, pt, n_prev, n_curr, sin_a, cos_a, d, jt);
        } else if sin_a < -1e-12 {
            // concave vertex: plain bevel between the two offset edges
            push_point(&mut out, pt, n_prev.x, n_prev.y, d);
            push_point(&mut out, pt, n_curr.x, n_curr.y, d);
        } else {
            // 180-degree (straight) vertex
            push_point(&mut out, pt, n_curr.x, n_curr.y, d);
        }
    }
    strip_duplicates(&mut out);
    out
}

pub fn inflate_paths(paths: &Paths64, delta: f64, jt: JoinType, et: EndType) -> Paths64 {
    let mut result: Paths64 = Vec::new();
    if et != EndType::Polygon {
        // The original test only offsets closed polygons; open-path
        // offsetting is intentionally not implemented.
        return result;
    }
    for path in paths {
        let mut p = path.clone();
        strip_duplicates(&mut p);
        if p.len() < 3 || area(&p) == 0.0 {
            continue;
        }
        if delta == 0.0 {
            result.push(p);
            continue;
        }
        let contour = offset_polygon(&p, delta, jt);
        if contour.len() >= 3 && area(&contour) != 0.0 {
            result.push(contour);
        }
    }
    result
}

