JoinType::Square => {
    // Clipper2's DoSquare: step delta units along the average of the
    // two edge-tangent unit vectors, then take the two perpendicular
    // points delta units either side of it.
    let mut vx = -n_prev.y + n_curr.y;
    let mut vy = n_prev.x - n_curr.x;
    let len = vx.hypot(vy);
    if len == 0.0 {
        // edges are collinear; fall back to the edge normal
        vx = n_curr.x;
        vy = n_curr.y;
    } else {
        vx /= len;
        vy /= len;
    }
    let qx = pt.x as f64 + delta * vx;
    let qy = pt.y as f64 + delta * vy;
    out.push(Point64::new(
        (qx + delta * vy).round() as i64,
        (qy - delta * vx).round() as i64,
    ));
    out.push(Point64::new(
        (qx - delta * vy).round() as i64,
        (qy + delta * vx).round() as i64,
    ));
}

